    char* new_string = _MALLOC(len+1,M_TEMP,M_WAITOK);
    if(new_string){
        memset(new_string,0,len+1);
        for(int i = 0;i < len;i++){
            byte = (int)string[i];
            byte = byte ^ (int)key[key_count];
            memcpy((void*)(uint64_t)new_string+i,&byte,sizeof(char));
            key_count++;
            if(key_count == strlen(key)){
                key_count = 0;
            }
        }
        return new_string;
    } 
    return 0;
}

